-- Package 3 (0074 + 0075) — POSTCHECK. READ ONLY: one SELECT, changes nothing.
-- Run once right after pkg3_apply.sql. Every row must be ok = true.
-- The rows of 0074_postcheck.sql and 0075_postcheck.sql, unchanged, each item prefixed with its migration.
with checks(item, ok, detail) as (
