  union all select '0074 reports, blocked_terms, account_suspensions: no direct access for signed-in or anonymous users', not has_table_privilege('authenticated', 'reports', 'select') and not has_table_privilege('authenticated', 'account_suspensions', 'select') and not has_table_privilege('authenticated', 'blocked_terms', 'select') and not has_table_privilege('anon', 'reports', 'select'), ''
  union all select '0074 player_blocks: no direct writes', not has_table_privilege('authenticated', 'player_blocks', 'insert') and not has_table_privilege('authenticated', 'player_blocks', 'delete'), ''
