  union all select '0074 join guard trigger on match_players: before insert, enabled', exists (select 1 from pg_trigger where tgname = 'match_players_block_guard' and tgenabled = 'O'), ''
  union all select '0074 chat read policy hides a blocked sender from the blocker', (select qual from pg_policies where tablename = 'match_messages' and policyname = 'match_messages: members read') like '%player_blocks%', ''
